// AdoptConfig holds the flags of sedum adopt.
type AdoptConfig struct {
	Generators, Records, Output, Recording    string
	Tests, AllowCommandAdopters, DryRun, JSON bool
}

func newAdoptCommand() *cobra.Command {
	var cfg AdoptConfig
	cmd := &cobra.Command{
		Use:   "adopt <path>...",
		Short: "Bring existing files under Sedum without a model",
		Long:  "Bring existing files under Sedum without a model. For each file, sedum splits it with the adopter its generator package declares, builds a recording, replays it, and keeps the file only if stripping the markers gives back the original. Files it cannot adopt are skipped and named with the reason. --dry-run writes only the recording; no model is called.",
		Args:  cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runAdopt(cmd.OutOrStdout(), cfg, args)
		},
	}
	cmd.Flags().StringVar(&cfg.Generators, "generators", "", "directory of generator packages")
	cmd.Flags().StringVar(&cfg.Records, "records", "", "directory of records")
	cmd.Flags().StringVar(&cfg.Output, "output", defaultOutput, "the project root the paths are relative to")
	cmd.Flags().StringVar(&cfg.Recording, "recording", "", "where to write the recording (default .sedum/adopt/adopt.json under --output)")
	cmd.Flags().BoolVar(&cfg.Tests, "tests", false, "also adopt test files")
	cmd.Flags().BoolVar(&cfg.AllowCommandAdopters, "allow-command-adopters", false, "allow adopters that run an external command")
	cmd.Flags().BoolVar(&cfg.DryRun, "dry-run", false, "write only the recording; change no files")
	cmd.Flags().BoolVar(&cfg.JSON, "json", false, "print the report as JSON")
	mustMarkRequired(cmd, "generators", "records")
	return cmd
}

func runAdopt(out io.Writer, cfg AdoptConfig, paths []string) error {
	rep, err := adopt.Run(adopt.Config{
		Root:          cfg.Output,
		Generators:    cfg.Generators,
		Records:       cfg.Records,
		Paths:         paths,
		Tests:         cfg.Tests,
		AllowCommand:  cfg.AllowCommandAdopters,
		DryRun:        cfg.DryRun,
		RecordingPath: cfg.Recording,
	})
	if err != nil {
		return err
	}
	if cfg.JSON {
		b, err := rep.JSON()
		if err != nil {
			return err
		}
		if _, err := out.Write(b); err != nil {
			return err
		}
	} else {
		if _, err := io.WriteString(out, rep.Text()); err != nil {
			return err
		}
	}
	if rep.Totals.Rejected > 0 {
		return fmt.Errorf("adopt: %d file(s) rejected", rep.Totals.Rejected)
	}
	return nil
}

func TestAdoptCommandText(t *testing.T) {
	gen, prov, proj := newAdoptCLIFixture(t)
	root := NewRootCommand()
	var buf bytes.Buffer
	root.SetOut(&buf)
	root.SetErr(&buf)
	root.SetArgs([]string{"adopt", "--generators", gen, "--records", prov, "--output", proj, "--dry-run", "."})
	if err := root.Execute(); err != nil {
		t.Fatal(err)
	}
	out := buf.String()
	for _, want := range []string{"adopt: 2 file(s): 1 adopted, 1 skipped, 0 rejected", "other_residual"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	got, err := os.ReadFile(filepath.Join(proj, "a.py"))
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "def f():\n    return 1\n" {
		t.Errorf("a.py changed on dry run: %q", got)
	}
}

func TestAdoptCommandJSON(t *testing.T) {
	gen, prov, proj := newAdoptCLIFixture(t)
	root := NewRootCommand()
	var buf bytes.Buffer
	root.SetOut(&buf)
	root.SetErr(&buf)
	root.SetArgs([]string{"adopt", "--generators", gen, "--records", prov, "--output", proj, "--dry-run", "--json", "."})
	if err := root.Execute(); err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(buf.Bytes(), &m); err != nil {
		t.Fatalf("output is not JSON: %v\n%s", err, buf.String())
	}
	totals, ok := m["totals"].(map[string]any)
	if !ok {
		t.Fatalf("missing totals in %v", m)
	}
	if totals["adopted"] != float64(1) {
		t.Errorf("adopted = %v, want 1", totals["adopted"])
	}
}

func TestAdoptCommandWritesTheFile(t *testing.T) {
	gen, prov, proj := newAdoptCLIFixture(t)
	root := NewRootCommand()
	var buf bytes.Buffer
	root.SetOut(&buf)
	root.SetErr(&buf)
	root.SetArgs([]string{"adopt", "--generators", gen, "--records", prov, "--output", proj, "."})
	if err := root.Execute(); err != nil {
		t.Fatalf("%v\n%s", err, buf.String())
	}
	a, err := os.ReadFile(filepath.Join(proj, "a.py"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(a), "# sedum:setThing") {
		t.Errorf("a.py not adopted:\n%s", a)
	}
	b, err := os.ReadFile(filepath.Join(proj, "b.py"))
	if err != nil {
		t.Fatal(err)
	}
	if string(b) != "import os\n\ndef g():\n    return 1\n" {
		t.Errorf("b.py changed:\n%s", b)
	}
}

func TestAdoptCommandRequiresGeneratorsAndRecords(t *testing.T) {
	root := NewRootCommand()
	var buf bytes.Buffer
	root.SetOut(&buf)
	root.SetErr(&buf)
	root.SetArgs([]string{"adopt", "."})
	err := root.Execute()
	if err == nil {
		t.Fatal("expected an error without --generators and --records")
	}
	if !strings.Contains(err.Error(), "generators") && !strings.Contains(err.Error(), "records") {
		t.Errorf("error does not mention the missing flag: %v", err)
	}
}

